import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { parseSchemaFile } from './load';

const schemaUrl = new URL('../../data/schema.json', import.meta.url);

// data/schema.json is generated by scripts/extract-schema.ps1; skip until it exists.
describe.skipIf(!existsSync(schemaUrl))('real extracted schema', () => {
  const schema = parseSchemaFile(readFileSync(schemaUrl, 'utf8'));

  it('covers many games with no extraction errors', () => {
    expect(Object.keys(schema.games).length).toBeGreaterThan(50);
    expect(schema.errors).toEqual([]);
  });

  it('every game has at least one option and every option sits in a group', () => {
    for (const game of Object.values(schema.games)) {
      expect(Object.keys(game.options).length, game.name).toBeGreaterThan(0);
      const grouped = new Set(game.groups.flatMap((group) => group.options));
      for (const key of Object.keys(game.options)) {
        expect(grouped.has(key), `${game.name}.${key} is in no group`).toBe(true);
      }
    }
  });
});
